const input = $input.first().json;
const body = input.body || input;

const text = String(body.text || '').trim();
const sender = body.sender || 'Unknown';
const conversationId = body.conversationId || body.sessionId || body.userId || body.sender || `conv_${Date.now()}`;
const history = Array.isArray(body.history) ? body.history : [];

const fileUrl = body.file_url || null;
const fileType = body.file_type || '';
const fileName = body.file_name || '';

const hasPdf = fileType === 'application/pdf' || fileName.toLowerCase().endsWith('.pdf');
const hasImage = fileType.startsWith('image/') || ['.png', '.jpg', '.jpeg', '.webp', '.gif'].some(ext => fileName.toLowerCase().endsWith(ext));
const hasAttachment = Boolean(fileUrl || hasPdf || hasImage);

return [{
  json: {
    sender,
    conversationId,
    message: text,
    history,
    file_url: fileUrl,
    file_type: fileType,
    file_name: fileName,
    hasPdf,
    hasImage,
    hasAttachment,
    messageId: body.messageId || '',
    timestamp: body.timestamp || new Date().toISOString()
  }
}];

const data = $input.first().json;
const normalizedText = (data.message || '').toLowerCase().trim().replace(/\s+/g, ' ');
const errorMatch = normalizedText.match(/\b(400|401|403|404|408|409|429|500|502|503|504)\b/);

let attachmentHint = 'none';
if (data.hasPdf) attachmentHint = 'pdf';
else if (data.hasImage) attachmentHint = 'image';

return [{
  json: {
    ...data,
    normalizedText,
    possibleErrorCode: errorMatch ? errorMatch[1] : null,
    attachmentHint,
    isEmptyMessage: !normalizedText && !data.hasAttachment
  }
}];

const item = $input.first().json;

const messagesRaw = item.messages || item.data?.messages || item.memory || item.chat_memory || [];
const memoryRows = Array.isArray(messagesRaw) ? messagesRaw : [];

function extractTicketId(text) {
  if (!text) return null;
  const match = String(text).match(/ticket[_\-\s]?id[:\s]+(ticket_[a-zA-Z0-9_-]+)/i);
  return match ? match[1] : null;
}

const historyFromDb = memoryRows.map(row => {
  const text = row.message_text || row.text || '';
  const matchedIssue = row.matched_issue || null;
  const explicitTicketId = row.ticket_id || null;
  const textTicketId = extractTicketId(text);

  const trustedTicketId =
    matchedIssue === 'manual_ticket' ||
    matchedIssue === 'existing_ticket_reused' ||
    /support ticket/i.test(text) ||
    /ticket id/i.test(text)
      ? (explicitTicketId || textTicketId)
      : null;

  return {
    role: row.role || 'user',
    text,
    intent: row.intent || null,
    matched_issue: matchedIssue,
    issue_summary: row.issue_summary || null,
    attachment_summary: row.attachment_summary || null,
    ticket_id: trustedTicketId,
    created_at: row.created_at || null
  };
}).filter(x => x.text);

const incomingHistory = Array.isArray(item.history) ? item.history : [];
const history = historyFromDb.length > 0 ? historyFromDb : incomingHistory;

let latestTicketEntry = null;
for (let i = history.length - 1; i >= 0; i--) {
  const h = history[i];
  if (
    h.ticket_id &&
    (h.matched_issue === 'manual_ticket' || h.matched_issue === 'existing_ticket_reused')
  ) {
    latestTicketEntry = h;
    break;
  }
}

return [{
  json: {
    ...item,
    history,
    latest_ticket_id: latestTicketEntry ? latestTicketEntry.ticket_id : null,
    latest_ticket_message: latestTicketEntry ? latestTicketEntry.text : null,
    has_existing_ticket: !!latestTicketEntry
  }
}];

const original = $('Build Conversation Context').first().json;
const extracted = $input.first().json || {};

return [{
  json: {
    ...original,
    attachment_text: extracted.attachment_text || '',
    attachment_summary: extracted.attachment_summary || '',
    attachment_extraction_method: extracted.extraction_method || 'none'
  }
}];

return [{
  json: {
    ...$json,
    apiPayload: {
      response: 'Please type your issue or upload a screenshot/PDF so I can help you.',
      sender: 'AI Assistant',
      category: 'empty_message',
      originalMessageId: $json.messageId || '',
      conversationId: $json.conversationId || ''
    }
  }
}];

const llmOutput = $input.first().json;
const original = $('Merge Attachment Context').first().json;

const raw = llmOutput?.content?.parts?.[0]?.text || llmOutput?.text || llmOutput?.output || '';

let cleaned = String(raw)
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    intent: 'unclear',
    confidence: 0,
    error_code: null,
    needs_ocr: false,
    direct_reply: null,
    normalized_user_need: 'Could not parse model output',
    needs_ticket: true
  };
}

return [{
  json: {
    ...original,
    parsed_intent: parsed
  }
}];

const history = $json.history || [];

const lastIssue = history
  .slice()
  .reverse()
  .find(m => {
    const intent = (m.intent || '').toLowerCase().trim();
    const issueSummary = (m.issue_summary || '').trim();
    const matchedIssue = (m.matched_issue || '').toLowerCase().trim();

    return (
      issueSummary &&
      intent !== 'greeting_or_ack' &&
      matchedIssue !== 'greeting_or_ack'
    );
  });

let reply;

if (!lastIssue) {
  reply = "I couldn't find any issue you reported earlier.";
} else {
  const issue = lastIssue.issue_summary;
  const ticket = lastIssue.ticket_id || null;

  reply = `Earlier you reported this issue: "${issue}".`;

  if (ticket) {
    reply += ` A support ticket was created with ID ${ticket}.`;
  }
}

return [{
  json: {
    ...$json,
    final_response_text: reply,
    final_category: 'issue_recall',
    conversationId: $json.conversationId || '',
    messageId: $json.messageId || ''
  }
}];

const reply = $json.parsed_intent?.direct_reply || 'Hello! How can I help you today?';

return [{
  json: {
    ...$json,
    final_response_text: reply,
    final_category: 'greeting_or_ack',
    apiPayload: {
      response: reply,
      sender: 'AI Assistant',
      category: 'greeting_or_ack',
      originalMessageId: $json.messageId || '',
      conversationId: $json.conversationId || ''
    }
  }
}];

return [{
  json: {
    conversationId: $json.conversationId || '',
    user_message: $json.message || '',
    assistant_message: $json.final_response_text || '',
    intent: $json.parsed_intent?.intent || 'greeting_or_ack',
    matched_issue: 'greeting_or_ack',
    issue_summary: null,
    attachment_summary: $json.attachment_summary || '',
    ticket_id: null,
    messageId: $json.messageId || ''
  }
}];

return [{
  json: {
    ...$json,
    apiPayload: {
      response: "Couldn't understand the text kindly describe your issue again",
      sender: 'AI Assistant',
      category: 'gibberish',
      originalMessageId: $json.messageId || '',
      conversationId: $json.conversationId || ''
    }
  }
}];

const item = $input.first().json;

const kb = [
  {
    short_issue: '404 Not Found',
    short_resolution_or_hint: 'The requested resource or endpoint does not exist. Verify the URL or webhook path.',
    example_subjects: ['Webhook not registered', 'API endpoint not found']
  },
  {
    short_issue: '401 Unauthorized',
    short_resolution_or_hint: 'Authentication failed. Check API keys, tokens, or login credentials.',
    example_subjects: ['Invalid API token']
  },
  {
    short_issue: '403 Forbidden',
    short_resolution_or_hint: 'Access to the resource is denied. Ensure proper permissions are granted.',
    example_subjects: ['Permission denied']
  },
  {
    short_issue: '500 Internal Server Error',
    short_resolution_or_hint: 'The server encountered an unexpected condition. Check backend logs for details.',
    example_subjects: ['Server crashed while processing request']
  },
  {
    short_issue: '503 Service Unavailable',
    short_resolution_or_hint: 'The service is temporarily unavailable due to overload or maintenance. Retry later.',
    example_subjects: ['Service temporarily unavailable']
  },
  {
    short_issue: 'Payment or invoice issue',
    short_resolution_or_hint: 'Check invoice upload, payment status, approval stage, or missing UTR.',
    example_subjects: ['Payment pending', 'Invoice issue']
  },
  {
    short_issue: 'System access not working',
    short_resolution_or_hint: 'Verify login rights, reset password, or enable the account.',
    example_subjects: ['Unable to login']
  },
  {
    short_issue: 'Bank account or IFSC update',
    short_resolution_or_hint: 'Verify bank details and update the account number or IFSC correctly.',
    example_subjects: ['Bank details update']
  },
  {
    short_issue: 'Loan disbursement pending',
    short_resolution_or_hint: 'Check the disbursement stage, bank validation, or pending borrower action.',
    example_subjects: ['Disbursement pending']
  },
  {
    short_issue: 'Ticket follow-up or no response',
    short_resolution_or_hint: 'Check ticket age and escalate if it has been pending too long.',
    example_subjects: ['No response on ticket']
  },
  {
    short_issue: 'Password reset request',
    short_resolution_or_hint: 'Reset the password or follow the account recovery flow.',
    example_subjects: ['Password reset']
  },
  {
    short_issue: 'App or portal bug',
    short_resolution_or_hint: 'Check the affected page, error pattern, browser, and recent changes.',
    example_subjects: ['Portal issue']
  },
  {
    short_issue: 'Unable to submit form',
    short_resolution_or_hint: 'Check mandatory fields, validation errors, session expiry, or access rights.',
    example_subjects: ['Form submission failed']
  },
  {
    short_issue: 'Document not opening or corrupted',
    short_resolution_or_hint: 'Check the file format/version or ask for the document to be resent.',
    example_subjects: ['File not opening']
  },
  {
    short_issue: 'Meeting link not working',
    short_resolution_or_hint: 'Verify the meeting link, invite permissions, and the correct signed-in account.',
    example_subjects: ['Meeting link issue']
  }
];

return [{
  json: {
    ...item,
    kb
  }
}];

const llmOutput = $input.first().json;
const original = $('KB Lookup').item.json;

const raw = llmOutput?.content?.parts?.[0]?.text || llmOutput?.text || llmOutput?.output || '';

let cleaned = String(raw)
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    matched_issue: 'no_match',
    short_resolution_or_hint: 'I could not confidently match this issue to the knowledge base.',
    confidence: 0,
    needs_ticket: true
  };
}

return [{
  json: {
    ...original,
    parsed_issue: parsed
  }
}];

const intent = $json.parsed_intent || {};
const issue = $json.parsed_issue || {};

let response = issue.short_resolution_or_hint || 'I found a likely match for your issue.';

if (intent.intent === 'follow_up') {
  response = `This looks like a follow-up to your earlier issue. ${response}`;
}

if (intent.needs_ocr) {
  response += ' If the screenshot or PDF contains the main error, make sure it is clearly visible so OCR can be added later.';
}

return [{
  json: {
    ...$json,
    final_response_text: response,
    final_category: issue.matched_issue || intent.intent || 'general_issue',
    apiPayload: {
      response,
      sender: 'AI Assistant',
      category: issue.matched_issue || intent.intent || 'general_issue',
      originalMessageId: $json.messageId || '',
      conversationId: $json.conversationId || ''
    }
  }
}];

return [{
  json: {
    conversationId: $json.conversationId || '',
    user_message: $json.message || '',
    assistant_message: $json.final_response_text || '',
    intent: $json.parsed_intent?.intent || 'general_issue',
    matched_issue: $json.final_category || $json.parsed_issue?.matched_issue || 'general_issue',
    issue_summary: $json.parsed_issue?.matched_issue || $json.parsed_intent?.normalized_user_need || $json.attachment_summary || $json.message || '',
    attachment_summary: $json.attachment_summary || '',
    ticket_id: null,
    messageId: $json.messageId || ''
  }
}];

const intent = $json.parsed_intent || {};
const issue = $json.parsed_issue || {};
const message = ($json.message || '').toLowerCase().trim();
const existingTicketId = $json.latest_ticket_id || null;
const history = Array.isArray($json.history) ? $json.history : [];

const wantsSupportPerson = /contact support|support person|human support|talk to support|connect me to support|connect to support|agent|human agent|representative|real person|customer care|escalate/i.test(message);
const asksForTicketId = /ticket id|existing ticket|my ticket|previous ticket|show ticket|ticket number/i.test(message);

const hasManualTicketInThisChat = history.some(h =>
  h.ticket_id &&
  (h.matched_issue === 'manual_ticket' || h.matched_issue === 'existing_ticket_reused')
);

const reuseExistingTicket =
  !!existingTicketId &&
  hasManualTicketInThisChat &&
  (
    wantsSupportPerson ||
    asksForTicketId ||
    issue.matched_issue === 'no_match'
  );

return [{
  json: {
    ...$json,
    conversationId: $json.conversationId || '',
    reuse_existing_ticket: reuseExistingTicket,
    existing_ticket_id: reuseExistingTicket ? existingTicketId : null,
    ticketPayload: {
      ticket_title: intent.error_code
        ? `Issue related to ${intent.error_code}`
        : (
            issue.matched_issue &&
            issue.matched_issue !== 'no_match'
              ? issue.matched_issue
              : 'Manual support ticket'
          ),
      ticket_description:
        intent.normalized_user_need ||
        $json.attachment_summary ||
        $json.message ||
        'Manual support review needed',
      category:
        issue.matched_issue &&
        issue.matched_issue !== 'no_match'
          ? issue.matched_issue
          : (intent.intent || 'general_issue'),
      priority: intent.intent === 'error_code_issue' ? 'High' : 'Medium'
    },
    messageId: $json.messageId || '',
    originalCategory:
      issue.matched_issue &&
      issue.matched_issue !== 'no_match'
        ? issue.matched_issue
        : (intent.intent || 'general_issue'),
    originalMessage: $json.message || '',
    originalIntent: intent.intent || 'general_issue',
    issue_summary:
      issue.matched_issue &&
      issue.matched_issue !== 'no_match'
        ? issue.matched_issue
        : (intent.normalized_user_need || $json.attachment_summary || $json.message || '')
  }
}];

const ticketId = $json.existing_ticket_id;

let response = `You already have an active support ticket for this chat. Ticket ID: ${ticketId}. I have kept the same ticket open and your request will continue there.`;

if (/ticket id|my ticket|existing ticket|ticket number/i.test(($json.originalMessage || '').toLowerCase())) {
  response = `Your existing support ticket ID is ${ticketId}.`;
}

return [{
  json: {
    ...$json,
    final_response_text: response,
    final_category: 'existing_ticket_reused',
    final_ticket_id: ticketId,
    apiPayload: {
      response,
      sender: 'AI Assistant',
      category: 'existing_ticket_reused',
      originalMessageId: $json.messageId || '',
      conversationId: $json.conversationId || '',
      ticket_id: ticketId
    }
  }
}];

return [{
  json: {
    conversationId: $json.conversationId || '',
    user_message: $json.originalMessage || '',
    assistant_message: $json.final_response_text || '',
    intent: $json.originalIntent || 'general_issue',
    matched_issue: 'existing_ticket_reused',
    issue_summary: $json.issue_summary || $json.originalMessage || '',
    attachment_summary: $json.attachment_summary || '',
    ticket_id: $json.final_ticket_id || $json.existing_ticket_id || null,
    messageId: $json.messageId || ''
  }
}];

const ticketResponse = $input.first().json;
const source = $('Prepare Ticket Payload').first().json;

const ticketId = ticketResponse.ticket_id || ticketResponse.id || 'generated';
const response = `I could not find a confident knowledge-base match, so I created a support ticket for you. Ticket ID: ${ticketId}. Our team will contact you shortly.`;

return [{
  json: {
    ...source,
    ticket_create_response: ticketResponse,
    final_response_text: response,
    final_category: 'manual_ticket',
    final_ticket_id: ticketId,
    apiPayload: {
      response,
      sender: 'AI Assistant',
      category: 'manual_ticket',
      originalMessageId: source.messageId || '',
      conversationId: source.conversationId || '',
      ticket_id: ticketId
    }
  }
}];

const source = $('Prepare Ticket Ack').first().json;

return [{
  json: {
    conversationId: source.conversationId || '',
    user_message: source.originalMessage || '',
    assistant_message: source.final_response_text || '',
    intent: source.originalIntent || 'general_issue',
    matched_issue: source.final_category || source.originalCategory || 'manual_ticket',
    issue_summary: source.issue_summary || source.originalMessage || '',
    attachment_summary: source.attachment_summary || '',
    ticket_id: source.final_ticket_id || null,
    messageId: source.messageId || ''
  }
}];
